    P(t, [('From international trade the following benefits are obtained:', 'بین الاقوامی تجارت سے درج ذیل فائدے حاصل ہوتے ہیں:', 'له نړیوالې سوداګرۍ لاندې ګټې ترلاسه کېږي:')])
